-- ============================================================
-- Shopee – Cơ sở dữ liệu bài tập lớn đề tài 19
-- Quản lý đơn hàng và đổi trả trong bán hàng trực tuyến
-- MySQL / MariaDB (XAMPP) · Import bằng phpMyAdmin hoặc mysql CLI
-- Mật khẩu demo: 123456 (đã băm bcrypt)
-- ============================================================
DROP DATABASE IF EXISTS orderflow;
CREATE DATABASE orderflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE orderflow;

CREATE TABLE users (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(100) NOT NULL,
  email VARCHAR(120) NOT NULL,
  phone VARCHAR(20) DEFAULT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role ENUM('admin','staff','customer') NOT NULL DEFAULT 'customer',
  status TINYINT NOT NULL DEFAULT 1 COMMENT '1=active 0=disabled',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email),
  KEY idx_users_role (role)
) ENGINE=InnoDB;

CREATE TABLE categories (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  code VARCHAR(10) NOT NULL,
  name VARCHAR(100) NOT NULL,
  description VARCHAR(255) DEFAULT NULL,
  emoji VARCHAR(10) DEFAULT NULL,
  status TINYINT NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_categories_code (code),
  UNIQUE KEY uq_categories_name (name)
) ENGINE=InnoDB;

CREATE TABLE products (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  sku VARCHAR(30) NOT NULL,
  name VARCHAR(150) NOT NULL,
  category_id INT UNSIGNED DEFAULT NULL,
  price DECIMAL(14,0) NOT NULL DEFAULT 0 COMMENT 'Giá hiện tại (đ có thể đổi)',
  stock INT NOT NULL DEFAULT 0 COMMENT 'Lượng hàng có thể bán',
  variants TEXT DEFAULT NULL COMMENT 'Chuỗi biến thể cách nhau dấu ;',
  emoji VARCHAR(10) DEFAULT NULL,
  images TEXT DEFAULT NULL COMMENT 'Danh sách URL ảnh, mỗi dòng một URL, tối đa 5',
  description TEXT DEFAULT NULL COMMENT 'Mô tả sản phẩm',
  specs TEXT DEFAULT NULL COMMENT 'Chi tiết sản phẩm, mỗi dòng Tên: Giá trị',
  status ENUM('active','hidden') NOT NULL DEFAULT 'active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_products_sku (sku),
  KEY idx_products_category (category_id),
  KEY idx_products_status (status),
  CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE product_variants (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  product_id INT UNSIGNED NOT NULL,
  sku VARCHAR(40) DEFAULT NULL,
  name VARCHAR(120) NOT NULL,
  price DECIMAL(14,0) DEFAULT NULL COMMENT 'NULL = dùng giá sản phẩm',
  stock INT NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_pv_product (product_id),
  UNIQUE KEY uq_pv_product_name (product_id, name),
  CONSTRAINT fk_pv_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE product_reviews (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  product_id INT UNSIGNED NOT NULL,
  reviewer_name VARCHAR(100) NOT NULL,
  rating TINYINT UNSIGNED NOT NULL,
  variant VARCHAR(120) DEFAULT NULL,
  comment TEXT DEFAULT NULL,
  images TEXT DEFAULT NULL COMMENT 'Danh sách URL ảnh review, mỗi dòng một URL',
  helpful_count INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_pr_product_created (product_id, created_at),
  KEY idx_pr_product_rating (product_id, rating),
  CONSTRAINT fk_pr_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE orders (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  order_code VARCHAR(20) NOT NULL,
  user_id INT UNSIGNED DEFAULT NULL COMMENT 'Tài khoản khách (có thể null với đơn nhập tay)',
  customer_name VARCHAR(100) NOT NULL,
  phone VARCHAR(20) DEFAULT NULL,
  address VARCHAR(255) DEFAULT NULL,
  order_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  payment_method ENUM('cod','bank','momo') NOT NULL DEFAULT 'cod',
  total_amount DECIMAL(14,0) NOT NULL DEFAULT 0,
  reserved_until DATETIME NULL COMMENT 'Thời gian hết hạn giữ hàng',
  status ENUM('cho_xac_nhan','da_xac_nhan','dang_giao','da_giao','da_huy') NOT NULL DEFAULT 'cho_xac_nhan',
  stock_restored TINYINT NOT NULL DEFAULT 0 COMMENT '1=đã hoàn kho khi hủy (chỉ 1 lần)',
  cancel_reason VARCHAR(255) DEFAULT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_orders_code (order_code),
  KEY idx_orders_user (user_id),
  KEY idx_orders_status (status),
  KEY idx_orders_date (order_date),
  CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE order_items (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  order_id INT UNSIGNED NOT NULL,
  product_id INT UNSIGNED NOT NULL,
  sku VARCHAR(30) DEFAULT NULL,
  product_name VARCHAR(150) NOT NULL COMMENT 'Snapshot tên tại thời điểm đặt',
  variant_id INT UNSIGNED DEFAULT NULL,
  variant VARCHAR(120) DEFAULT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(14,0) NOT NULL COMMENT 'Snapshot giá tại thời điểm đặt',
  line_total DECIMAL(14,0) NOT NULL,
  PRIMARY KEY (id),
  KEY idx_oi_order (order_id),
  KEY idx_oi_product (product_id),
  KEY idx_oi_variant (variant_id),
  CONSTRAINT fk_oi_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
  CONSTRAINT fk_oi_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
  CONSTRAINT fk_oi_variant FOREIGN KEY (variant_id) REFERENCES product_variants (id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Giỏ hàng (chưa đặt đơn) – người dùng chọn hàng trước khi xác nhận
CREATE TABLE carts (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id INT UNSIGNED NOT NULL,
  status ENUM('active','checked_out','abandoned') NOT NULL DEFAULT 'active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_carts_user (user_id),
  KEY idx_carts_status (status),
  CONSTRAINT fk_cart_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE cart_items (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  cart_id INT UNSIGNED NOT NULL,
  product_id INT UNSIGNED NOT NULL,
  variant_id INT UNSIGNED DEFAULT NULL,
  variant VARCHAR(120) NOT NULL DEFAULT '',
  quantity INT NOT NULL DEFAULT 1,
  unit_price DECIMAL(14,0) NOT NULL COMMENT 'Giá sản phẩm tại thời điểm thêm vào giỏ',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_ci_cart (cart_id),
  KEY idx_ci_product (product_id),
  KEY idx_ci_variant (variant_id),
  UNIQUE KEY uq_ci_cart_product_variant (cart_id, product_id, variant),
  CONSTRAINT fk_ci_cart FOREIGN KEY (cart_id) REFERENCES carts (id) ON DELETE CASCADE,
  CONSTRAINT fk_ci_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
  CONSTRAINT fk_ci_variant FOREIGN KEY (variant_id) REFERENCES product_variants (id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Phiếu giữ hàng (reservation) – giữ tồn kho tạm thời khi đặt đơn, chưa trừ kho thật
CREATE TABLE reservations (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  reservation_code VARCHAR(20) NOT NULL,
  order_id INT UNSIGNED DEFAULT NULL COMMENT 'Đơn hàng đã xác nhận liên kết (null nếu vẫn đang giữ)',
  user_id INT UNSIGNED DEFAULT NULL,
  product_id INT UNSIGNED NOT NULL,
  variant_id INT UNSIGNED DEFAULT NULL,
  variant VARCHAR(120) DEFAULT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(14,0) NOT NULL COMMENT 'Giá chốt khi đặt',
  status ENUM('pending','confirmed','released','expired') NOT NULL DEFAULT 'pending',
  reserved_until DATETIME NOT NULL COMMENT 'Thời gian hết hạn giữ hàng',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reservations_code (reservation_code),
  KEY idx_reservations_order (order_id),
  KEY idx_reservations_user (user_id),
  KEY idx_reservations_product (product_id),
  KEY idx_reservations_variant (variant_id),
  KEY idx_reservations_status (status),
  KEY idx_reservations_expires (reserved_until),
  CONSTRAINT fk_res_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE SET NULL,
  CONSTRAINT fk_res_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_res_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
  CONSTRAINT fk_res_variant FOREIGN KEY (variant_id) REFERENCES product_variants (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE payments (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  payment_code VARCHAR(20) NOT NULL,
  order_id INT UNSIGNED NOT NULL,
  amount DECIMAL(14,0) NOT NULL,
  method ENUM('cod','bank','momo') NOT NULL DEFAULT 'cod',
  status ENUM('thanh_cong','cho_xu_ly','that_bai','hoan_tien') NOT NULL DEFAULT 'cho_xu_ly',
  idempotency_key VARCHAR(64) DEFAULT NULL COMMENT 'Chống xử lý trùng thông báo',
  note VARCHAR(255) DEFAULT NULL,
  processed_at DATETIME DEFAULT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_payments_code (payment_code),
  UNIQUE KEY uq_payments_idem (idempotency_key),
  KEY idx_payments_order (order_id),
  KEY idx_payments_status (status),
  CONSTRAINT fk_payments_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE payment_events (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  payment_id INT UNSIGNED NOT NULL,
  order_id INT UNSIGNED NOT NULL,
  idempotency_key VARCHAR(64) DEFAULT NULL,
  result VARCHAR(20) NOT NULL,
  outcome VARCHAR(40) NOT NULL COMMENT 'created|accepted|failed|refunded|duplicate_replay|late_rejected_refund|ignored_terminal',
  detail VARCHAR(255) DEFAULT NULL,
  created_by INT UNSIGNED DEFAULT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_pe_payment (payment_id),
  KEY idx_pe_order (order_id),
  KEY idx_pe_key (idempotency_key),
  CONSTRAINT fk_pe_payment FOREIGN KEY (payment_id) REFERENCES payments (id) ON DELETE CASCADE,
  CONSTRAINT fk_pe_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
  CONSTRAINT fk_pe_user FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE code_sequences (
  name VARCHAR(32) NOT NULL,
  value INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (name)
) ENGINE=InnoDB;

CREATE TABLE shipments (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  shipment_code VARCHAR(20) NOT NULL,
  order_id INT UNSIGNED NOT NULL,
  carrier VARCHAR(60) NOT NULL,
  tracking_code VARCHAR(40) NOT NULL,
  ship_date DATETIME DEFAULT NULL,
  status ENUM('cho_lay_hang','dang_van_chuyen','da_giao','that_bai') NOT NULL DEFAULT 'cho_lay_hang',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_shipments_code (shipment_code),
  UNIQUE KEY uq_shipments_order (order_id),
  KEY idx_shipments_status (status),
  CONSTRAINT fk_shipments_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE return_requests (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  return_code VARCHAR(20) NOT NULL,
  order_id INT UNSIGNED NOT NULL,
  user_id INT UNSIGNED DEFAULT NULL,
  customer_name VARCHAR(100) NOT NULL,
  reason TEXT NOT NULL,
  status ENUM('cho_xu_ly','da_chap_nhan','tu_choi','da_hoan_tat') NOT NULL DEFAULT 'cho_xu_ly',
  processed_by INT UNSIGNED DEFAULT NULL,
  processed_at DATETIME DEFAULT NULL,
  process_note VARCHAR(255) DEFAULT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_return_code (return_code),
  KEY idx_rr_order (order_id),
  KEY idx_rr_user (user_id),
  KEY idx_rr_status (status),
  CONSTRAINT fk_rr_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
  CONSTRAINT fk_rr_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_rr_processor FOREIGN KEY (processed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE return_items (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  return_request_id INT UNSIGNED NOT NULL,
  order_item_id INT UNSIGNED NOT NULL,
  product_id INT UNSIGNED NOT NULL,
  product_name VARCHAR(150) NOT NULL,
  quantity_requested INT NOT NULL,
  quantity_accepted INT NOT NULL DEFAULT 0,
  unit_price DECIMAL(14,0) NOT NULL COMMENT 'Giá đã chốt trong đơn',
  refund_amount DECIMAL(14,0) NOT NULL DEFAULT 0,
  restock TINYINT NOT NULL DEFAULT 1 COMMENT '1=nhập lại kho khi hoàn tất',
  PRIMARY KEY (id),
  KEY idx_ri_req (return_request_id),
  KEY idx_ri_item (order_item_id),
  CONSTRAINT fk_ri_req FOREIGN KEY (return_request_id) REFERENCES return_requests (id) ON DELETE CASCADE,
  CONSTRAINT fk_ri_oi FOREIGN KEY (order_item_id) REFERENCES order_items (id) ON DELETE RESTRICT,
  CONSTRAINT fk_ri_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE inventory_movements (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  product_id INT UNSIGNED NOT NULL,
  order_id INT UNSIGNED DEFAULT NULL,
  change_type ENUM('nhap','xuat','huy_don','tra_hang','dieu_chinh') NOT NULL,
  quantity INT NOT NULL COMMENT 'Số dương = cộng, số âm = trừ',
  note VARCHAR(255) DEFAULT NULL,
  created_by INT UNSIGNED DEFAULT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_im_product (product_id),
  KEY idx_im_order (order_id),
  CONSTRAINT fk_im_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
  CONSTRAINT fk_im_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE SET NULL,
  CONSTRAINT fk_im_user FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE sessions (
  id CHAR(64) NOT NULL COMMENT 'token ngẫu nhiên (không lưu cookie)',
  user_id INT UNSIGNED NOT NULL,
  expires_at DATETIME NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_sessions_user (user_id),
  KEY idx_sessions_expires (expires_at),
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE order_history (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  order_id INT UNSIGNED NOT NULL,
  from_status VARCHAR(20) DEFAULT NULL,
  to_status VARCHAR(20) NOT NULL,
  note VARCHAR(255) DEFAULT NULL,
  changed_by INT UNSIGNED DEFAULT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_oh_order (order_id),
  CONSTRAINT fk_oh_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
  CONSTRAINT fk_oh_user FOREIGN KEY (changed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB;

